"""Five main figures with eight documented panels each, using measured data."""
from pathlib import Path
import json,hashlib,itertools,textwrap
import numpy as np
import pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.colors import ListedColormap
import networkx as nx
import tifffile

P=Path(__file__).resolve().parent;ROOT=P.parent;R=P/'results';F=P/'figures';S=P/'panel_data'
for folder in [F,S]:folder.mkdir(exist_ok=True)
BLUE='#246C9C';ORANGE='#BC6538';GREEN='#4D7F61';GRAY='#78858D';PALE='#D5DDE2';PURPLE='#846A9C';COLORS=[BLUE,ORANGE,GREEN,PURPLE,'#A89343']
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':8,'axes.titlesize':8.5,'axes.labelsize':7.5,'xtick.labelsize':7,'ytick.labelsize':7,'axes.spines.top':False,'axes.spines.right':False,'axes.unicode_minus':False,'svg.fonttype':'none','pdf.fonttype':42,'savefig.dpi':320})
REGISTRY=[]
ORDER=['DYNLL1','TP53BP1','H2AX','RNF8','RNF168','MRE11','RAD50','CYP7B1','MAT1A','SLC35A2','SMARCE1']
BATCHES=['20220914_Run1','20221009_Run2','20221017_Run3','20221024_Run4','20221109_Run5']
LABELS=['R1','R2','R3','R4','R5']

def layout(n=8):
    fig,axes=plt.subplots(4 if n==8 else 3,2,figsize=(7.2,9.1 if n==8 else 7.4));fig.subplots_adjust(left=.11,right=.98,bottom=.07,top=.97,hspace=.78,wspace=.47);return fig,axes.ravel()
def emit(ax,figure,letter,title,data,unit,note,source):
    ax.set_title(r'$\mathbf{'+letter+r'}$  '+textwrap.fill(title,40),loc='left',pad=8,fontweight='normal',fontsize=8);name=f'{figure}_{letter}.csv';data.to_csv(S/name,index=False);REGISTRY.append({'figure':figure,'panel':letter,'title':title,'source_data':f'phase11/panel_data/{name}','sample_unit':unit,'interpretation':note,'input_source':source,'status':'measured data or documented study design','independent_spatial_replication':False})
def save(fig,figure):
    for ext in ['png','svg','pdf']:fig.savefig(F/f'{figure}.{ext}',facecolor='white',bbox_inches='tight',pad_inches=.08)
    plt.close(fig)
def zero(ax,vertical=False):
    (ax.axvline if vertical else ax.axhline)(0,color='black',lw=.6,zorder=0)
def dateplot(ax,a,value='effect',color=BLUE):
    a=a.set_index('batch').reindex(BATCHES);ax.plot(range(5),a[value],color=color,marker='o',ms=3,lw=1);ax.set_xticks(range(5),LABELS);zero(ax)
def gene_guides(ax,contrast):
    a=pd.read_parquet(ROOT/f'phase10/results/guides/{contrast}.parquet');a=a[a.gene.isin(['DYNLL1','DYNLL2'])].copy();cols=[c for c in a if c.startswith('LFC_r')];x=0;ticks=[];labels=[]
    for gene,color in [('DYNLL1',BLUE),('DYNLL2',ORANGE)]:
        g=a[a.gene.eq(gene)];ticks.append(x+(len(g)-1)/2);labels.append(gene)
        for _,row in g.iterrows():
            v=row[cols].to_numpy(float);ax.scatter(x+np.linspace(-.10,.10,len(v)),v,s=8,color=color,alpha=.55);ax.scatter(x,v.mean(),marker='D',s=12,facecolors=color if row.eligible else 'none',edgecolors=color);x+=1
        x+=1
    ax.set_xticks(ticks,labels);zero(ax);ax.set_ylabel('Guide log2 ratio');return a

def main1():
    fig,axs=layout();manifest=pd.read_csv(ROOT/'phase6/frozen_contrasts.csv');d=manifest[manifest.gene.eq('DYNLL1')].sort_values('batch');first=d.iloc[0];plate=first.target_plate;fields=[f'{plate}__A02__s0',f'{plate}__{first.target_well}__s0'];imgs=[];geoms=[]
    for field in fields:
        path=next(p for p in [ROOT/f'phase5/data/jump_raw/images/{field}.tif',ROOT/f'phase6/data/raw/images/{field}.tif'] if p.exists());imgs.append(tifffile.imread(path));gp=next(p for p in [ROOT/f'phase5/data/jump_raw/geometry/{field}.parquet',ROOT/f'phase6/data/raw/geometry/{field}.parquet'] if p.exists());geoms.append(pd.read_parquet(gp));
    vmin,vmax=np.quantile(imgs[0],[.01,.995]);immeta=[]
    for ax,letter,label,img,g,field in zip(axs[:2],['A','B'],['Source nontargeting control','DYNLL1 pooled perturbation'],imgs,geoms,fields):
        x0=img.shape[1]//2-256;y0=img.shape[0]//2-256;crop=img[y0:y0+512,x0:x0+512];ax.imshow(crop,cmap='gray',vmin=vmin,vmax=vmax);q=g[g.ar.ge(1.2)&g.x.between(x0,x0+512)&g.y.between(y0,y0+512)].copy()
        for row in q.itertuples():
            dx=.35*row.major*np.sin(row.theta);dy=.35*row.major*np.cos(row.theta);ax.plot([row.x-x0-dx,row.x-x0+dx],[row.y-y0-dy,row.y-y0+dy],color='#65C6E1',lw=.45)
        ax.plot([20,120],[492,492],color='white',lw=1.2);ax.text(20,477,'100 px',color='white',fontsize=5.5);ax.set_axis_off();emit(ax,'main_figure1',letter,label,q,'one fixed field and its nuclear axes','Site0 of the first acquisition date, centered512-pixel window. Both images use the same NT-defined display range and100-pixel display bar. These examples were fixed by date/site rather than phenotype and are not biological replicates.','phase6 frozen DYNLL1 contrast; original DNA TIFF and geometry');immeta.append({'field':field,'crop_x0':x0,'crop_y0':y0,'crop_width':512,'crop_height':512,'NT_display_min':float(vmin),'NT_display_max':float(vmax)});tifffile.imwrite(P/'data'/f'{letter}_{field}_crop.tif',crop)
    (S/'fixed_image_display_metadata.json').write_text(json.dumps(immeta,indent=2))
    ax=axs[2];coverage=manifest.groupby(['gene','batch']).size().unstack(fill_value=0).reindex(index=ORDER,columns=BATCHES,fill_value=0);ax.imshow(coverage,cmap=ListedColormap(['#EFEFEF',BLUE]),vmin=0,vmax=1,aspect='auto');ax.set_yticks(range(len(ORDER)),ORDER,fontsize=6.5);ax.set_xticks(range(5),LABELS);emit(ax,'main_figure1','C','Targeted cohort coverage',coverage.reset_index(),'gene by acquisition date','A filled cell indicates a canonical target well. MRE11 has four dates. Repeated plates within one date are not substituted for missing biological batches.','phase6/frozen_contrasts.csv')
    primary=pd.read_csv(ROOT/'phase6/results/adaptive_conditional_contrasts.csv');dyn=primary[primary.gene.eq('DYNLL1')];ax=axs[3];dateplot(ax,dyn);ax.set_ylabel('Adjusted local alignment');emit(ax,'main_figure1','D','Primary date level contrasts',dyn,'five acquisition dates','Original control-trained, position-corrected primary endpoint. The same four-crRNA pool was used on all dates; repeated positive dates do not establish independent-guide replication.','phase6/results/adaptive_conditional_contrasts.csv')
    matched=pd.read_csv(ROOT/'phase6/results/direct_matching_contrasts.csv');matched=matched[matched.gene.eq('DYNLL1')];joined=dyn[['batch','effect']].merge(matched[['batch','effect']],on='batch',suffixes=('_model','_matching'));ax=axs[4]
    for i,row in joined.iterrows():ax.plot([0,1],[row.effect_model,row.effect_matching],color=COLORS[i],marker='o',ms=3,lw=1)
    ax.set_xticks([0,1],['Model','Matching']);ax.set_ylabel('Position corrected contrast');zero(ax);emit(ax,'main_figure1','E','Control matching sensitivity',joined,'paired estimates within five dates','Model adjustment and direct matching use related images and controls. Lines compare estimators, not independent studies. The matching effect is positive on four dates.','phase6 primary and direct_matching contrasts')
    fields=pd.read_csv(ROOT/'phase6/results/adaptive_conditional_fields.csv');wells=pd.read_csv(ROOT/'phase6/results/adaptive_conditional_wells.csv');records=[]
    for row in d.itertuples():
        b=wells[wells.batch.eq(row.batch)];source=b[b.plate.eq(row.target_plate)&b.well.isin(row.source_NT_wells.split(';'))].residual.mean();pos=b[b.plate.eq(row.negative_plate)&b.well.eq(row.negative_well)].residual.mean();anchor=b[b.plate.eq(row.negative_plate)&b.well.isin(row.anchor_wells.split(';'))].residual.mean();q=fields[fields.batch.eq(row.batch)&fields.plate.eq(row.target_plate)&fields.well.eq(row.target_well)].copy();q['field_contrast']=q.residual-source-pos+anchor;records.append(q)
    f=pd.concat(records);ax=axs[5]
    for i,batch in enumerate(BATCHES):
        v=f[f.batch.eq(batch)].field_contrast.to_numpy();ax.scatter(i+np.linspace(-.12,.12,len(v)),v,s=9,color=COLORS[i],alpha=.7)
    ax.set_xticks(range(5),LABELS);ax.set_ylabel('Within well field contrast');zero(ax);emit(ax,'main_figure1','F','Within well field heterogeneity',f,'nine fields nested within each date','Each field uses the fixed whole-well control offset for its date. Fields are technical spatial samples and do not increase biological n beyond five dates.','phase6 adaptive_conditional fields and wells')
    loo=pd.read_csv(R/'leave_one_date_out.csv');ax=axs[6];ax.plot(range(5),loo.mean_effect,marker='o',color=BLUE,ms=3);ax.set_xticks(range(5),LABELS);ax.set_xlabel('Omitted date');ax.set_ylabel('Mean of four remaining dates');zero(ax);emit(ax,'main_figure1','G','Leave one date out',loo,'five dependence diagnostics','Each estimate omits one date from the existing primary endpoint. This diagnoses dependence on a date and is not replication. All retained means are positive.','phase11/results/leave_one_date_out.csv')
    radial=pd.read_csv(R/'new_descriptor_contrasts.csv');radial=radial[radial.metric.str.startswith('radius_')];radial['radius_multiplier']=radial.metric.str.replace('radius_','').str.replace('p','.').astype(float);ax=axs[7]
    for i,batch in enumerate(BATCHES):q=radial[radial.batch.eq(batch)].sort_values('radius_multiplier');ax.plot(q.radius_multiplier,q.effect,marker='o',ms=2.5,lw=.8,color=COLORS[i],alpha=.65)
    mean=radial.groupby('radius_multiplier').effect.mean();ax.plot(mean.index,mean.values,color='black',lw=1.8);ax.set_xlabel('Density adaptive radius multiplier');ax.set_ylabel('Common focal alignment contrast');zero(ax);emit(ax,'main_figure1','H','Spatial scale of alignment excess',radial,'five dates across four radii','Exploratory field-level calibration using a common focal set at all radii. Thin lines are dates and black is their mean. This estimator differs from the original nucleus-level model and does not measure dynamics.','phase11 new multiscale common-focal analysis');save(fig,'main_figure1')

def main2():
    fig,axs=layout();primary=pd.read_csv(ROOT/'phase6/results/adaptive_conditional_contrasts.csv');mat=primary.pivot(index='gene',columns='batch',values='effect').reindex(index=ORDER,columns=BATCHES);ax=axs[0];im=ax.imshow(mat,cmap='RdBu_r',vmin=-.06,vmax=.06,aspect='auto');ax.set_yticks(range(len(ORDER)),ORDER,fontsize=6.5);ax.set_xticks(range(5),LABELS);plt.colorbar(im,ax=ax,fraction=.045,pad=.02).ax.tick_params(labelsize=6);emit(ax,'main_figure2','A','Gene specific alignment contrasts',mat.reset_index(),'gene by acquisition date','The full fixed panel is shown, including nonconfirming recruitment-module genes and seeded targeting backgrounds. Missing MRE11 coverage remains blank.','phase6 original primary contrasts')
    c=pd.read_csv(R/'new_descriptor_contrasts.csv');metrics=['log_area','log_AR','solidity','log_density','scaled_NND','global_pair_order','position_axis_coupling','log_DNA_proxy'];m=c[c.metric.isin(metrics)].groupby(['gene','metric']).effect_control_SD.mean().unstack().reindex(index=ORDER,columns=metrics);ax=axs[1];im=ax.imshow(m,cmap='RdBu_r',vmin=-3,vmax=3,aspect='auto');ax.set_yticks(range(len(ORDER)),ORDER,fontsize=6.5);ax.set_xticks(range(8),['Area','AR','Sol','Dens','NND','S2','Pos','DNA'],rotation=45,ha='right',fontsize=6.5);plt.colorbar(im,ax=ax,fraction=.045,pad=.02).ax.tick_params(labelsize=6);emit(ax,'main_figure2','B','Exploratory nuclear feature profiles',m.reset_index(),'gene means across four or five dates','New field-level contrasts are divided by the corresponding control-field residual SD for display. Color limits are fixed at plus/minus3; full uncapped values are retained. No new confirmatory descriptor tests are claimed.','phase11 field-level descriptor models')
    ax=axs[2];q=c[c.gene.eq('DYNLL1')&c.metric.eq('log_AR')];dateplot(ax,q);ax.set_ylabel('Log nuclear AR contrast');emit(ax,'main_figure2','C','Nuclear elongation after adjustment',q,'five date-level nuclear shape contrasts','Aspect ratio summaries include all valid nuclei, with density/guide-status/batch adjustment and no adjustment for the outcome itself. These are nuclear, not cell-outline measurements.','phase11 new log_AR field summaries')
    ax=axs[3];q=c[c.gene.eq('DYNLL1')&c.metric.isin(['log_density','scaled_NND'])]
    for metric,color,label in [('log_density',GRAY,'Density'),('scaled_NND',BLUE,'Scaled NND')]:
        z=q[q.metric.eq(metric)].set_index('batch').reindex(BATCHES);ax.plot(range(5),z.effect_control_SD,marker='o',ms=3,color=color,lw=1,label=label)
    ax.set_xticks(range(5),LABELS);ax.set_ylabel('Contrast in control SD units');ax.legend(frameon=False,fontsize=6.5,loc='lower left');zero(ax);emit(ax,'main_figure2','D','Density and nuclear spacing',q,'five dates for each of two distinct observables','NND is median nearest-neighbor distance scaled by the square root of field nuclear density. It is a nuclear spacing descriptor rather than a confluence or jamming measurement.','phase11 log_density and scaled_NND contrasts')
    ax=axs[4];q=c[c.gene.eq('DYNLL1')&c.metric.eq('global_pair_order')];dateplot(ax,q);ax.set_ylabel('Global pair order contrast');emit(ax,'main_figure2','E','Field wide director order',q,'five date-level contrasts','The finite-sample corrected pair order summarizes the entire field and differs from local alignment excess. Its date pattern is not used to choose a preferred endpoint.','phase11 global_pair_order descriptor')
    ax=axs[5];q=c[c.gene.eq('DYNLL1')&c.metric.eq('position_axis_coupling')];dateplot(ax,q);ax.set_ylabel('Axis position coupling contrast');emit(ax,'main_figure2','F','Axis and neighbor position coupling',q,'five date-level contrasts','The nearest-centroid displacement is compared with the focal nuclear axis after a field-angle reassignment null. Row-axis angles are explicitly converted to the image x frame, checked with synthetic ellipses. This does not measure polarity.','phase11 position_axis_coupling descriptor')
    module=json.loads((ROOT/'phase6/results/module_tests.json').read_text())['adaptive_conditional'];v=np.array(module['batch_effects']);null=np.array([np.mean(v*s) for s in itertools.product([-1,1],repeat=5)]);ax=axs[6];ax.hist(null,bins=12,color=PALE,edgecolor='white');ax.axvline(v.mean(),color=ORANGE,lw=1.6);ax.set_xlabel('Five date module mean');ax.set_ylabel('Sign assignments');ax.text(.03,.95,f'Positive-tail P = {module["exact_one_sided_p"]:.4f}',transform=ax.transAxes,va='top',fontsize=7);emit(ax,'main_figure2','G','Frozen recruitment module test',pd.DataFrame({'null_mean':null,'observed_mean':v.mean()}),'32 sign assignments of five batch-level module contrasts','The original positive phenocopy hypothesis failed. All null assignments and the observed negative module mean are shown without switching to a different module.','phase6 frozen TP53BP1 H2AX RNF8 RNF168 module')
    base=pd.read_csv(ROOT/'phase6/results/DNA_proxy_same_sample_baseline_contrasts.csv').groupby('gene').effect.mean();dna=pd.read_csv(ROOT/'phase6/results/DNA_proxy_adjusted_contrasts.csv').groupby('gene').effect.mean();q=pd.concat([base.rename('baseline'),dna.rename('DNA_adjusted')],axis=1).reset_index();ax=axs[7];ax.scatter(q.baseline,q.DNA_adjusted,color=GRAY,s=15);g=q[q.gene.eq('DYNLL1')];ax.scatter(g.baseline,g.DNA_adjusted,color=BLUE,s=25);lo=min(q[['baseline','DNA_adjusted']].min())-.005;hi=max(q[['baseline','DNA_adjusted']].max())+.005;ax.plot([lo,hi],[lo,hi],color='black',lw=.6);ax.set_xlabel('Same sample baseline');ax.set_ylabel('DNA proxy adjusted contrast');emit(ax,'main_figure2','H','DNA fluorescence proxy sensitivity',q,'gene means using the same positive-DNA subset','The integrated DNA signal is an imaging proxy, not a validated cell-cycle state. This same-sample comparison avoids mistaking sample changes for covariate effects.','phase6 DNA_proxy_same_sample_baseline and DNA_proxy_adjusted contrasts');save(fig,'main_figure2')

def main3():
    fig,axs=layout();whole=pd.read_csv(R/'hTERT_genome_fitness_and_interactions.csv');audit=pd.read_csv(ROOT/'phase10/results/hTERT_DYNLL1_DYNLL2_reagent_and_interaction_audit.csv');ax=axs[0];ax.axis('off')
    for y,label,color in [(.75,'Parental U2OS',GRAY),(.32,'hTERT engineered U2OS',BLUE)]:
        ax.text(.01,y,label,color=color,fontsize=8);ax.annotate('',xy=(.9,y-.10),xytext=(.15,y-.10),arrowprops={'arrowstyle':'->','color':color,'lw':1});ax.text(.12,y-.25,'Day 0',fontsize=7);ax.text(.73,y-.25,'Day 21',fontsize=7)
    ax.text(.98,.94,'Two labeled replicates per arm',ha='right',fontsize=6);ax.text(.01,-.20,'Published normalized counts',fontsize=6.5);emit(ax,'main_figure3','A','Assayed hTERT screen design',pd.DataFrame({'context':['parental','hTERT_engineered'],'replicates':[2,2],'day0':[0,0],'endpoint_day':[21,21]}),'published study design','This diagram describes the actual screen arms and timepoints. Metadata does not establish that the two labeled mutant replicates are separate independently edited clones.','GSE226994 sample metadata')
    ax=axs[1];ax.scatter(whole.parental_LFC,whole.engineered_LFC,s=2,color=PALE,rasterized=True);lo=min(whole.parental_LFC.min(),whole.engineered_LFC.min());hi=max(whole.parental_LFC.max(),whole.engineered_LFC.max());ax.plot([lo,hi],[lo,hi],color='black',lw=.6)
    for gene,color in [('DYNLL1',BLUE),('DYNLL2',ORANGE)]:q=whole[whole.gene.eq(gene)].iloc[0];ax.scatter(q.parental_LFC,q.engineered_LFC,color=color,s=22);ax.annotate(gene,(q.parental_LFC,q.engineered_LFC),xytext=(3,-10 if gene=='DYNLL1' else 3),textcoords='offset points',fontsize=6.5)
    ax.set_xlabel('Parental gene median log2 ratio');ax.set_ylabel('Engineered gene median log2 ratio');emit(ax,'main_figure3','B','Genome wide fitness context',whole,'gene-level summaries in two distinct contexts','Effects are equal means of replicate guide medians. The scatter describes context and does not create additional biological replicates.','phase10 parental and engineered gene effects')
    dyn=audit[audit.gene.eq('DYNLL1')].sort_values('cut_position');cols=['LFC_r1_WT','LFC_r2_WT','LFC_r1_KO','LFC_r2_KO'];ax=axs[2];im=ax.imshow(dyn[cols],vmin=-3.2,vmax=3.2,cmap='RdBu_r',aspect='auto');ax.set_yticks(range(4),[str(int(x)) for x in dyn.cut_position],fontsize=6.5);ax.set_xticks(range(4),['WT1','WT2','Mut1','Mut2'],fontsize=6.5)
    for i in range(4):
        for j in range(4):ax.text(j,i,f'{dyn[cols].iloc[i,j]:.1f}',ha='center',va='center',fontsize=6.5,color='white' if abs(dyn[cols].iloc[i,j])>1.8 else 'black')
    emit(ax,'main_figure3','C','All four DYNLL1 guides',dyn,'four guides measured in both labeled replicates of each arm','Every DYNLL1 guide is shown, including the guide that increases in abundance. Cut coordinates come from the official Brunello annotation.','phase10 official-guide hTERT audit')
    ax=axs[3];ax.scatter(whole.delta_r1,whole.delta_r2,s=2,color=PALE,rasterized=True);zero(ax);zero(ax,True)
    for gene,color in [('DYNLL1',BLUE),('DYNLL2',ORANGE)]:q=whole[whole.gene.eq(gene)].iloc[0];ax.scatter(q.delta_r1,q.delta_r2,s=24,color=color);ax.annotate(gene,(q.delta_r1,q.delta_r2),xytext=(3,-9 if gene=='DYNLL1' else 3),textcoords='offset points',fontsize=6.5)
    rho=json.loads((R/'context_summary.json').read_text())['hTERT_replicate_interaction_spearman'];ax.text(.02,.98,f'Genome Spearman rho = {rho:.3f}',transform=ax.transAxes,va='top',fontsize=7);ax.set_xlabel('Replicate 1 genotype interaction');ax.set_ylabel('Replicate 2 genotype interaction');emit(ax,'main_figure3','D','Interaction replicate agreement',whole,'genome-wide within-guide interaction summaries','Replicate interaction agreement is low even though within-arm fitness summaries correlate more strongly. The selected DYNLL1 candidate is negative in both replicate medians, but its rank remains exploratory.','phase11 hTERT genome interactions')
    values=dyn[['delta_r1','delta_r2']].to_numpy();rows=[]
    for i,row in enumerate(dyn.itertuples()):rows.append({'omitted_cut_coordinate':int(row.cut_position),'mean_interaction':float(np.median(np.delete(values,i,axis=0),axis=0).mean())})
    q=pd.DataFrame(rows);ax=axs[4];ax.scatter(q.mean_interaction,range(4),color=BLUE,s=20);ax.axvline(float(np.median(values,axis=0).mean()),color=GRAY,lw=.8,ls='--');zero(ax,True);ax.set_yticks(range(4),q.omitted_cut_coordinate.astype(str),fontsize=6.5);ax.set_xlabel('Remaining guide median interaction');emit(ax,'main_figure3','E','Leave one guide out',q,'four guide-omission diagnostics','A negative estimate remains after each guide omission, but these correlated sensitivity calculations do not supply additional independent reagents.','phase10 hTERT target-guide interaction audit')
    matched=pd.read_csv(R/'hTERT_parental_fitness_matched500.csv');target=float(whole.loc[whole.gene.eq('DYNLL1'),'mean_delta'].iloc[0]);ax=axs[5];ax.hist(matched.mean_delta,bins=35,color=PALE,edgecolor='white');ax.axvline(target,color=BLUE,lw=1.6);ax.set_xlabel('Median genotype interaction');ax.set_ylabel('Parental fitness matched genes');ax.text(.03,.96,'DYNLL1 rank 1 of 501',transform=ax.transAxes,va='top',fontsize=7);emit(ax,'main_figure3','F','Matched parental fitness background',matched,'500 nearest parental-fitness genes plus target reference','This reference conditions on basal fitness. A rank within a post hoc matched set is not a P value, FDR or proof of synthetic lethality. DYNLL2 is excluded from the matching pool.','phase11 hTERT_parental_fitness_matched500.csv')
    regional=pd.read_csv(ROOT/'phase10/results/hTERT_chr12_within_2Mb_controls.csv');g=pd.read_csv(ROOT/'phase10/results/hTERT_all_gene_interactions.csv.gz');targetrow=g[g.gene.eq('DYNLL1')].iloc[0];ax=axs[6];ax.scatter((regional.cut_position-targetrow.cut_position)/1e6,regional.mean_delta,s=11,color=GRAY);ax.scatter(0,targetrow.mean_delta,s=25,color=BLUE);zero(ax);ax.set_xlabel('Distance from DYNLL1 in Mb');ax.set_ylabel('Median genotype interaction');emit(ax,'main_figure3','G','Regional chromosome context',pd.concat([regional,g[g.gene.eq('DYNLL1')]],ignore_index=True),'DYNLL1 and 52 other genes within2Mb','Nearby genes provide a positional comparison. This analysis does not estimate copy number, correct Cas9 cutting effects or establish clonal independence.','phase10 hTERT regional controls')
    context=pd.read_csv(ROOT/'phase10/results/hTERT_published_pathway_context.csv');ax=axs[7];ax.scatter(context.mean_delta,range(len(context)),s=12,color=GRAY);ax.set_yticks(range(len(context)),context.gene,fontsize=6);ax.invert_yaxis();zero(ax,True);ax.set_xlabel('Median genotype interaction');emit(ax,'main_figure3','H','Published pathway context',context,'15 fixed Fanconi BRCA PARP and TERT context genes','All fixed context genes are retained, including genes with mixed or positive effects. Their inclusion does not establish a shared causal pathway for DYNLL1 nuclear alignment.','phase10 full published-pathway context table');save(fig,'main_figure3')

def main4():
    fig,axs=layout();degree=pd.read_csv(R/'APMS_all_node_degree.csv');neighbors=pd.read_csv(ROOT/'phase10/results/APMS_paralog_neighbors.csv');ax=axs[0];ax.hist(degree.degree,bins=np.logspace(0,np.log10(degree.degree.max()+1),35),color=PALE,edgecolor='white');ax.set_xscale('log');ax.set_yscale('log');ax.set_xlabel('Undirected network degree');ax.set_ylabel('Proteins')
    for gene,color in [('DYNLL1',BLUE),('DYNLL2',ORANGE)]:value=int(degree.loc[degree.gene.eq(gene),'degree'].iloc[0]);ax.axvline(value,color=color,lw=1,label=f'{gene} = {value}')
    ax.legend(frameon=False,fontsize=6,loc='upper right')
